CREATE TABLE `providers` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`code` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`name` VARCHAR(160) NOT NULL,`target_url` VARCHAR(1000) CHARACTER SET ascii NOT NULL,`access_mode` ENUM('public_page','public_rss','official_api','authenticated_browser','import','manual') NOT NULL,`markets_json` JSON NOT NULL,`languages_json` JSON NOT NULL,`fields_json` JSON NOT NULL,`schedule_minutes` INT UNSIGNED NOT NULL,`concurrency_limit` SMALLINT UNSIGNED NOT NULL,`timeout_ms` INT UNSIGNED NOT NULL,`retry_limit` SMALLINT UNSIGNED NOT NULL,`circuit_failure_threshold` SMALLINT UNSIGNED NOT NULL,`dedupe_key` VARCHAR(255) NOT NULL,`retention_days` INT UNSIGNED NOT NULL,`failure_rules_json` JSON NOT NULL,`parser_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`healthcheck_url` VARCHAR(1000) CHARACTER SET ascii NULL,`owner_label` VARCHAR(120) NOT NULL,`status` ENUM('draft','disabled','enabled') NOT NULL DEFAULT 'draft',`version` INT UNSIGNED NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_providers_code` (`code`),KEY `idx_providers_status_updated` (`status`,`updated_at`),CONSTRAINT `fk_providers_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),CONSTRAINT `fk_providers_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `provider_versions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`snapshot_json` JSON NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` ENUM('created','updated') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_provider_version` (`provider_id`,`version`),KEY `idx_provider_version_trace` (`trace_id`),CONSTRAINT `fk_provider_versions_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_provider_versions_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `provider_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`route` VARCHAR(180) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_provider_operation` (`actor_id`,`route`,`idempotency_key`),KEY `idx_provider_operation_created` (`created_at`),CONSTRAINT `fk_provider_operations_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_provider_operations_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
